import math
from crank_nicolson import solve, exact_solution

N=801; T=0.2; alpha=0.5
dx=1/(N-1)
xs,_=solve(N,1e-4,T,alpha)
ex=[exact_solution(x,T,alpha) for x in xs]

def err_vs_exact(dt):
    _,u=solve(N,dt,T,alpha)
    return max(abs(u[i]-ex[i+1]) for i in range(len(u)))

# self-convergence vs reference with dt_ref much smaller, same grid
_,uref=solve(N,1.25e-4,T,alpha)
def err_vs_ref(dt):
    _,u=solve(N,dt,T,alpha)
    return max(abs(u[i]-uref[i]) for i in range(len(u)))

for name,f in (("vs exact",err_vs_exact),("vs ref",err_vs_ref)):
    errs={dt:f(dt) for dt in (4e-3,2e-3,1e-3)}
    p=[math.log(errs[a]/errs[b])/math.log(2) for a,b in ((4e-3,2e-3),(2e-3,1e-3))]
    print(name, {k:f"{v:.3e}" for k,v in errs.items()}, "orders:", [f"{p0:.3f}" for p0 in p])

# L2 norm vs exact
import statistics
def l2(dt):
    _,u=solve(N,dt,T,alpha)
    return math.sqrt(sum((u[i]-ex[i+1])**2 for i in range(len(u)))*dx)
errs={dt:l2(dt) for dt in (4e-3,2e-3,1e-3)}
print("L2 vs exact", {k:f"{v:.3e}" for k,v in errs.items()},
      "orders:", [f"{math.log(errs[a]/errs[b])/math.log(2):.3f}" for a,b in ((4e-3,2e-3),(2e-3,1e-3))])
