import math

from crank_nicolson import (
    crank_nicolson_step,
    exact_solution,
    initial_condition,
    max_error,
    solve,
)


def test_accuracy_N201_dt_1e3():
    err = max_error(t_final=0.2, N=201, dt=1e-3)
    assert err < 5e-5, f"max error {err:.3e} not below 5e-5"


def _temporal_errors(N, t_final, dts, dt_ref, alpha=0.5):
    """Max-norm difference vs a fine-dt reference solution on the SAME grid.

    The spatial discretization is identical for all runs, so it cancels and
    the differences isolate the temporal (Crank-Nicolson O(dt^2)) error.
    """
    _, u_ref = solve(N, dt_ref, t_final, alpha)
    return {
        dt: max(
            abs(u[i] - u_ref[i])
            for i in range(len(u_ref))
        )
        for dt in (solve(N, dt, t_final, alpha)[1] and dts)
        for u in [solve(N, dt, t_final, alpha)[1]]
    }


def test_temporal_convergence_order():
    N = 801
    t_final = 0.2
    dts = (4e-3, 2e-3, 1e-3)
    errors = {}
    _, u_ref = solve(N, 1.25e-4, t_final)
    for dt in dts:
        _, u = solve(N, dt, t_final)
        errors[dt] = max(abs(u[i] - u_ref[i]) for i in range(len(u)))
    p1 = math.log(errors[4e-3] / errors[2e-3]) / math.log(2.0)
    p2 = math.log(errors[2e-3] / errors[1e-3]) / math.log(2.0)
    order = (p1 + p2) / 2.0
    assert 1.8 <= order <= 2.2, f"measured order {order:.3f}, errors={errors}"

